import json
import subprocess
import sys


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if len(argv) != 1:
        return 1

    target_path = argv[0]
    try:
        ok = subprocess.run(
            [sys.executable, target_path, "ok"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
        )
        bad = subprocess.run(
            [sys.executable, target_path, "bad"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
        )
    except OSError:
        return 1

    if ok.returncode != 0 or bad.returncode != 2:
        return 1

    try:
        value = json.loads(ok.stdout)
    except (json.JSONDecodeError, UnicodeDecodeError):
        return 1

    return 0 if value == {"value": "ok"} else 1


if __name__ == "__main__":
    sys.exit(main())

